using Crown.Core;
using System.Text.Json.Nodes;

internal static class StageTwentyTwoSpecs
{
    private static void Assert(bool value,string text){if(!value)throw new Exception(text);}
    internal static GameState Fixture(bool ports=true)
    {
        var s=StageTwentyOneSpecs.Fixture();
        foreach(var t in s.Tiles.Where(t=>t.X>=10&&t.X<=32&&t.Y>=13&&t.Y<=15))t.Terrain=t.Y==14?Terrain.Ocean:Terrain.Coast;
        if(ports){s.Cities[0].Buildings.Add(Navy.Port);s.Cities[1].Buildings.Add(Navy.Port);}s.InvalidateLogistics();return s;
    }
    private static Unit Ship(GameState s,int owner,int x=12,int y=13,string model="coastal_galley")=>Engine.AddUnit(s,owner,y*s.Width+x,UnitKind.Ship,model);
    private static void Tech(GameState s,int owner=0,int eras=3){s.Factions[owner].Technologies.UnionWith(EpochCatalog.All.Take(eras).SelectMany(e=>e.Technologies));for(int i=0;i<eras;i++)s.Factions[owner].EpochChoices[i]=0;}
    private static void War(GameState s){s.Relation(0,1).War=true;s.InvalidateLogistics();}
    private static void Valid(GameState s)=>SaveGame.Deserialize(SaveGame.Serialize(s));
    public static void Run(Action<string,Action> test)
    {
        test("The complete naval catalog references legal technologies and distinct ship roles",()=>{Assert(Navy.Models.Length==9&&Navy.Models.All(m=>Content.Technologies.Any(t=>t.Id==m.Technology)&&m.Role==UnitKind.Ship&&Content.Project(m.Id).Unit==UnitKind.Ship),"Invalid ship catalog");});
        test("A seaport requires a coastal city and the full epoch campaign",()=>{var s=Fixture(false);Tech(s);Assert(Engine.SetProject(s,s.Cities[0].Id,Navy.Port).Success,"Coastal port rejected");Assert(Navy.ProjectError(s,s.Cities[2],Navy.Port)!=null,"Inland port permitted");s.EpochCampaign=false;Assert(Navy.ProjectError(s,s.Cities[0],Navy.Port)!=null,"Legacy port permitted");});
        test("Ships require their actual technology and a completed launch port",()=>{var s=Fixture(false);var c=s.Cities[0];Assert(!Engine.SetProject(s,c.Id,"coastal_galley").Success,"Free technology");Tech(s);Assert(!Engine.SetProject(s,c.Id,"coastal_galley").Success,"Missing port ignored");c.Buildings.Add(Navy.Port);Assert(Engine.SetProject(s,c.Id,"coastal_galley").Success,"Legal galley rejected");});
        test("A port is built through real city production and adds actual food gold and upkeep",()=>{var s=Fixture(false);Tech(s);var c=s.Cities[0];double food=Engine.CityYields(s,c).Food,gold=Engine.CityYields(s,c).Gold,cost=Engine.Economy(s,0).AdministrationCost;c.ProductionPaused=false;Engine.SetProject(s,c.Id,Navy.Port);c.Production=119.9;Assert(Engine.EndTurn(s).Success&&c.Buildings.Contains(Navy.Port),"Port did not complete");Assert(Engine.CityYields(s,c).Food>food&&Engine.CityYields(s,c).Gold>gold&&Engine.Economy(s,0).AdministrationCost>=cost+2,"Port only decorative");Valid(s);});
        test("Shipbuilding spends production and launches on water instead of the city center",()=>{var s=Fixture();Tech(s);var c=s.Cities[0];c.ProductionPaused=false;Engine.SetProject(s,c.Id,"coastal_galley");c.Production=99.9;Assert(Engine.EndTurn(s).Success,"Ship turn rejected");var ship=s.Units.Single(u=>u.Owner==0&&Navy.IsShip(u));Assert(ship.Tile!=c.Tile&&Navy.Water(s.Tiles[ship.Tile])&&ship.ModelId=="coastal_galley"&&c.Production<100,"Ship created free or on land");Valid(s);});
        test("Unavailable launch berths block new work without discarding invested production",()=>{var s=Fixture();Tech(s);var c=s.Cities[0];c.ProductionPaused=false;Engine.SetProject(s,c.Id,"coastal_galley");c.Production=20;foreach(var t in World.Neighbors(s,c.Tile).Where(Navy.Water))Engine.AddUnit(s,1,t.Id,UnitKind.Ship,"coastal_galley");Assert(ProductionPlanning.CurrentBlock(s,c)!=null&&Engine.EndTurn(s).Success&&c.Production==20&&!s.Units.Any(u=>u.Owner==0&&Navy.IsShip(u)),"Blocked launch spent or invented work");});
        test("Naval movement spends one point per water field and never walks onto land",()=>{var s=Fixture();var u=Ship(s,0);int sea=World.Neighbors(s,u.Tile).First(t=>t.Terrain==Terrain.Coast&&t.Id!=u.Tile).Id;double actions=u.Actions;Assert(Engine.Move(s,u.Id,sea).Success&&u.Actions==actions-1,"Sea movement cost wrong");string before=SaveGame.Serialize(s);Assert(!Engine.Move(s,u.Id,s.Cities[0].Tile).Success&&SaveGame.Serialize(s)==before,"Ship moved onto land");});
        test("Land infantry cannot sail and early galleys cannot cross deep ocean",()=>{var s=Fixture();var u=Ship(s,0);var ocean=World.Neighbors(s,u.Tile).First(t=>t.Terrain==Terrain.Ocean);Assert(!Navigation.CanEnter(s,u,ocean)&&!Engine.Move(s,u.Id,ocean.Id).Success,"Early ocean crossing");var infantry=Engine.AddUnit(s,0,s.Cities[0].Tile,UnitKind.Spearmen);Assert(!Engine.Move(s,infantry.Id,u.Tile).Success,"Infantry walked on water");});
        test("Ocean capable models can cross open sea using the same route engine",()=>{var s=Fixture();var u=Ship(s,0,12,13,"carrack");int sea=World.Neighbors(s,u.Tile).First(t=>t.Terrain==Terrain.Ocean).Id;Assert(Engine.Move(s,u.Id,sea).Success&&u.Actions==u.MaxActions-1,"Ocean vessel blocked");Valid(s);});
        test("Naval routes respect unexplored fields and foreign peaceful waters",()=>{var s=Fixture();var u=Ship(s,0);int id=World.Neighbors(s,u.Tile).First(t=>t.Terrain==Terrain.Coast).Id;s.Tiles[id].Explored=false;string before=SaveGame.Serialize(s);Assert(!Engine.OrderMove(s,u.Id,id).Success&&SaveGame.Serialize(s)==before,"Unknown sea route leaked");s.Tiles[id].Explored=true;s.Tiles[id].Owner=1;Assert(!Engine.Move(s,u.Id,id).Success,"Peaceful border crossed");War(s);Assert(Engine.Move(s,u.Id,id).Success,"War sea route rejected");});
        test("Multi-turn naval orders preserve water destinations through a save reload",()=>{var s=Fixture();var u=Ship(s,0);int target=13*s.Width+17;Assert(Engine.OrderMove(s,u.Id,target).Success&&u.Destination==target,"No continuing sea order");var loaded=SaveGame.Deserialize(SaveGame.Serialize(s));Assert(loaded.Units.Single(v=>v.Id==u.Id).Destination==target,"Water order lost");Assert(Engine.EndTurn(s).Success&&u.Tile==target&&u.Destination==null,"Automatic voyage failed");Valid(s);});
        test("Ship supply comes from active seaports rather than inland city roads",()=>{var s=Fixture();var u=Ship(s,0);Assert(Engine.Supplied(s,u),"Home port failed to supply");s.Cities[0].Buildings.Remove(Navy.Port);s.InvalidateLogistics();Assert(!Engine.Supplied(s,u),"Inland roads supplied a ship");});
        test("An isolated water basin cannot receive supplies across land",()=>{var s=Fixture();var u=Ship(s,0,35,5);s.Tiles[u.Tile].Terrain=Terrain.Coast;Assert(!Engine.Supplied(s,u),"Supplies crossed land");});
        test("A wartime blockade disables port output and ship supply while maintenance remains",()=>{var s=Fixture();var u=Ship(s,0,14,13);double gold=Engine.CityYields(s,s.Cities[0]).Gold,upkeep=Navy.Upkeep(s,0);Ship(s,1,12,13);War(s);Assert(Navy.Blockaded(s,s.Cities[0])&&!Navy.ActivePort(s,s.Cities[0])&&!Engine.Supplied(s,u)&&Engine.CityYields(s,s.Cities[0]).Gold<gold*.75&&Navy.Upkeep(s,0)==upkeep,"Blockade lacks real consequences");});
        test("A peaceful foreign ship does not impose a blockade or erase port income",()=>{var s=Fixture();double gold=Engine.CityYields(s,s.Cities[0]).Gold;Ship(s,1);Assert(!Navy.Blockaded(s,s.Cities[0])&&Engine.CityYields(s,s.Cities[0]).Gold==gold,"Peaceful blockade invented");});
        test("Lifting a blockade immediately restores port activity and supply",()=>{var s=Fixture();var u=Ship(s,0,14,13);var enemy=Ship(s,1);War(s);Assert(!Engine.Supplied(s,u),"Missing initial blockade");s.Units.Remove(enemy);s.InvalidateLogistics();Assert(Navy.ActivePort(s,s.Cities[0])&&Engine.Supplied(s,u),"Blockade remained stale");});
        test("An enemy ship does not directly cut land road supply through naval adjacency",()=>{var s=Fixture();var land=Engine.AddUnit(s,0,s.Cities[0].Tile,UnitKind.Spearmen);Ship(s,1);War(s);Assert(Engine.Supplied(s,land),"Naval blockade incorrectly erased land supply");});
        test("Ship combat requires war and spends ordinary attack actions",()=>{var s=Fixture();var u=Ship(s,0);var enemy=Ship(s,1,13,13);Assert(!Engine.Move(s,u.Id,enemy.Tile).Success,"Peace attack");War(s);Assert(Engine.Move(s,u.Id,enemy.Tile).Success&&enemy.Health<100&&u.Actions==0&&u.Health==100,"Naval combat costs or damage wrong");Valid(s);});
        test("Early galleys cannot bombard land while ocean warships can",()=>{var s=Fixture();War(s);var u=Ship(s,1);Assert(!Engine.PreviewAttack(s,u.Id,s.Cities[0].Tile).Valid,"Galley bombarded city");u.ModelId="carrack";u.Actions=u.MaxActions;Assert(Engine.PreviewAttack(s,u.Id,s.Cities[0].Tile).Valid,"Later coastal bombardment blocked");});
        test("Naval bombardment can reduce a coastal city to zero but cannot capture it",()=>{var s=Fixture();War(s);var u=Ship(s,1,12,13,"carrack");s.Cities[0].Health=1;Assert(Engine.Move(s,u.Id,s.Cities[0].Tile).Success&&s.Cities[0].Health==0&&s.Cities[0].Owner==0&&Navy.Water(s.Tiles[u.Tile]),"Ship captured city or entered land");});
        test("Melee infantry cannot attack ships across the shoreline but ranged troops can",()=>{var s=Fixture();War(s);var enemy=Ship(s,1);var infantry=Engine.AddUnit(s,0,s.Cities[0].Tile,UnitKind.Spearmen);Assert(!Engine.PreviewAttack(s,infantry.Id,enemy.Tile).Valid,"Melee crossed domains");infantry.Kind=UnitKind.Archer;Assert(Engine.Move(s,infantry.Id,enemy.Tile).Success&&enemy.Health<100,"Shore ranged defense failed");});
        test("Ships reject fortification and convoy escort but can use ordinary recovery",()=>{var s=Fixture();var u=Ship(s,0);string before=SaveGame.Serialize(s);Assert(!Engine.SetMilitaryOrder(s,u.Id,MilitaryOrder.Fortify).Success&&SaveGame.Serialize(s)==before,"Ship dug trenches");u.Health=50;Assert(Engine.SetMilitaryOrder(s,u.Id,MilitaryOrder.Recover).Success&&u.Health==50&&u.Actions==0,"Recovery granted immediate healing");Assert(Engine.EndTurn(s).Success&&u.Health>50,"Naval recovery did not use turn rules");Valid(s);});
        test("Naval modernization requires a safe active home port and pays actual gold",()=>{var s=Fixture();Tech(s,0,7);var u=Ship(s,0);u.Health=75;u.Experience=3;double gold=s.Player.Gold;int price=UnitModels.UpgradeCost(s,u,Navy.Models.Single(m=>m.Id=="carrack"));Assert(Engine.UpgradeUnit(s,u.Id,"carrack").Success&&u.ModelId=="carrack"&&u.Health==75&&u.Experience==3&&u.Actions==0&&s.Player.Gold==gold-price,"Upgrade bypassed cost or healed");Valid(s);});
        test("A supplied ship away from a port cannot modernize at sea",()=>{var s=Fixture();Tech(s,0,7);var u=Ship(s,0,16,13);Assert(Engine.Supplied(s,u)&&!Engine.UpgradeUnit(s,u.Id,"carrack").Success,"Open sea modernization");});
        test("Ships do not consume land army garrison assignments",()=>{var s=Fixture();War(s);var ship=Ship(s,1,20,13);Assert(!MilitaryStrategy.Plan(s,1).Assignments.Any(a=>a.UnitId==ship.Id),"Land command took a ship");});
        test("Coastal AI chooses legal port construction then a technology appropriate fleet",()=>{var s=Fixture(false);Tech(s,1);var c=s.Cities[1];Assert(Navy.AiProject(s,c)?.Id==Navy.Port,"AI ignored its coast");c.Buildings.Add(Navy.Port);Assert(Navy.AiProject(s,c)?.Id=="coastal_galley","AI chose an illegal ship");});
        test("Naval AI fires through normal combat and never gives itself free movement or health",()=>{var s=Fixture();War(s);var enemy=Ship(s,0,19,13);var u=Ship(s,1,20,13);uint random=s.RandomState;Engine.RunNavalAi(s,1);Assert(enemy.Health<100&&u.Health==100&&u.Actions==0&&s.RandomState==random,"AI did not fire or cheated");Valid(s);});
        test("The naval AI executor cannot take control of the player's fleet",()=>{var s=Fixture();Ship(s,0);string before=SaveGame.Serialize(s);Engine.RunNavalAi(s,0);Assert(SaveGame.Serialize(s)==before,"Player fleet commandeered");});
        test("V21 preserves fleets water orders blockades and deterministic future turns",()=>{var s=Fixture();Ship(s,0);Ship(s,1,20,13);War(s);var copy=SaveGame.Deserialize(SaveGame.Serialize(s));Assert(copy.Version==21&&SaveGame.Serialize(copy)==SaveGame.Serialize(s),"Fleet roundtrip diverged");for(int i=0;i<3;i++){s.PendingEvent=copy.PendingEvent=null;Assert(Engine.EndTurn(s).Success&&Engine.EndTurn(copy).Success,"Naval turn failed");Assert(SaveGame.Serialize(s)==SaveGame.Serialize(copy),"Naval future diverged");}Valid(s);});
        test("V20 migration retains the old world without inventing ships and preserves its exact backup",()=>{var s=Fixture(false);s.Version=20;string old=SaveGame.Serialize(s);var loaded=SaveGame.Deserialize(old);Assert(loaded.Version==21&&loaded.Units.Count==s.Units.Count&&loaded.RandomState==s.RandomState&&!loaded.Cities.Any(c=>c.Buildings.Contains(Navy.Port)),"Migration invented fleet history");string dir=Path.Combine(Path.GetTempPath(),"crown-navy-"+Guid.NewGuid());Directory.CreateDirectory(dir);string path=Path.Combine(dir,"campaign.crown");try{File.WriteAllText(path,old);SaveGame.Write(loaded,path);Assert(File.ReadAllText(path+".v20.bak")==old&&SaveGame.Read(path).Version==21,"V20 backup lost");}finally{foreach(string p in new[]{path,path+".tmp",path+".v20.bak"})File.Delete(p);Directory.Delete(dir);}});
        test("Save validation rejects wrong naval domains models orders and forged old formats",()=>{foreach(int mode in Enumerable.Range(0,6)){var s=Fixture();var u=Ship(s,0);switch(mode){case 0:u.Tile=s.Cities[0].Tile;break;case 1:u.ModelId="legion";break;case 2:u.ModelId=null;break;case 3:u.Tile=14*s.Width+12;break;case 4:u.Order=MilitaryOrder.Fortify;break;case 5:s.Version=20;break;}bool bad=false;try{Valid(s);}catch(InvalidDataException){bad=true;}Assert(bad,"Malformed fleet accepted");}});
        test("Saved ports on inland cities are rejected",()=>{var s=Fixture();s.Cities[2].Buildings.Add(Navy.Port);bool bad=false;try{Valid(s);}catch(InvalidDataException){bad=true;}Assert(bad,"Inland port save accepted");});
        test("Repeated real naval turns keep every ship afloat and every land army on land",()=>{var s=Fixture();War(s);Ship(s,0);Ship(s,1,20,13);for(int i=0;i<12;i++){s.PendingEvent=null;Assert(Engine.EndTurn(s).Success,"Naval campaign stalled");Assert(s.Units.All(u=>Navy.IsShip(u)?Navy.TerrainAllowed(s,u,s.Tiles[u.Tile]):s.Tiles[u.Tile].Passable),"A unit crossed its terrain domain");Valid(s);}});
    }
}
